{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "The close tropane analog [N-methyl-11C]β-CIT showed high brain radioactivity in cynomolgus monkeys, with 5.5% of injected radioactivity in the brain 10 minutes after IV injection, directly demonstrating robust CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "The closely related tropane analog [125I]IPCIT reached 9.2% of the injected dose in baboon brain by whole-body imaging, confirming substantial brain uptake in a primate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "The tropane analog [18F]-R-FIPCT showed high initial striatal uptake of 4.5% dose/g in rats, supporting high brain penetration for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "The N-methyl tropane derivative [11C]benztropine showed clear brain uptake in human and baboon PET studies, supporting CNS access for N-methyl-tropane compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "The basic N-methyl piperidinyl benzoate analog BMP showed extremely high brain uptake (>14% ID/g in all brain regions) in mice, demonstrating that ionizable N-methyl esters of this type can cross the BBB extensively.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is cocaine, a tropane ester. Multiple close tropane analogs with high assay-transfer scores show direct, robust brain uptake in primates and rodents, overriding the physicochemical prior that predicted low passive permeability due to ionization. The experimental evidence strongly supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct quantitative brain-to-plasma ratio for cocaine itself is included in the provided records, but the consistent high brain uptake of closely related tropane analogs provides strong transferable evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

